// Given classes for ex11 .. ex14 (pointer-based, same as the chapter 6 and 7 slides).
// Do not edit this file: write only the function your exercise asks for, in your rendu file.
#ifndef STACK_QUEUE_H
#define STACK_QUEUE_H

typedef int StackItemType;
typedef int QueueItemType;

class Stack {
public:
    Stack() : topPtr(nullptr) {}
    Stack(const Stack& aStack) : topPtr(nullptr) {
        StackNode** tail = &topPtr;
        for (StackNode* cur = aStack.topPtr; cur != nullptr; cur = cur->next) {
            *tail = new StackNode{cur->item, nullptr};
            tail = &(*tail)->next;
        }
    }
    ~Stack() { while (pop()) {} }
    Stack& operator=(const Stack&) = delete;

    bool isEmpty() const { return topPtr == nullptr; }
    bool push(StackItemType newItem) { topPtr = new StackNode{newItem, topPtr}; return true; }
    bool pop() {
        if (isEmpty()) return false;
        StackNode* temp = topPtr;
        topPtr = topPtr->next;
        delete temp;
        return true;
    }
    bool pop(StackItemType& stackTop) {
        if (isEmpty()) return false;
        stackTop = topPtr->item;
        return pop();
    }
    bool getTop(StackItemType& stackTop) const {
        if (isEmpty()) return false;
        stackTop = topPtr->item;
        return true;
    }

    void reverse();                                    // ex11

private:
    struct StackNode {
        StackItemType item;
        StackNode* next;
    };
    StackNode* topPtr;
};

class Queue {
public:
    Queue() : backPtr(nullptr), frontPtr(nullptr) {}
    Queue(const Queue& Q) : backPtr(nullptr), frontPtr(nullptr) {
        for (QueueNode* cur = Q.frontPtr; cur != nullptr; cur = cur->next) enqueue(cur->item);
    }
    ~Queue() { while (dequeue()) {} }
    Queue& operator=(const Queue&) = delete;

    bool isEmpty() const { return backPtr == nullptr; }
    bool enqueue(QueueItemType newItem) {
        QueueNode* newPtr = new QueueNode{newItem, nullptr};
        if (isEmpty()) frontPtr = newPtr;
        else backPtr->next = newPtr;
        backPtr = newPtr;
        return true;
    }
    bool dequeue() {
        if (isEmpty()) return false;
        QueueNode* tempPtr = frontPtr;
        if (frontPtr == backPtr) frontPtr = backPtr = nullptr;
        else frontPtr = frontPtr->next;
        delete tempPtr;
        return true;
    }
    bool dequeue(QueueItemType& queueFront) {
        if (isEmpty()) return false;
        queueFront = frontPtr->item;
        return dequeue();
    }
    bool getFront(QueueItemType& queueFront) const {
        if (isEmpty()) return false;
        queueFront = frontPtr->item;
        return true;
    }

    bool moveToFront(QueueItemType value);             // ex12
    int removeAll(QueueItemType value);                // ex14

private:
    struct QueueNode {
        QueueItemType item;
        QueueNode* next;
    };
    QueueNode* backPtr;
    QueueNode* frontPtr;
};

void reverseQueue(Queue& q);                           // ex13

#endif
